import clsx from 'clsx';
import { isEmpty } from 'lodash-es';
import { useEffect, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { useStore } from '~/app/store/store';
import { 수취인_입력Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { RemitRequestDTO } from '~/entities/exchange/api/dtos/types';
import { useFindRecipientMutation } from '~/entities/exchange/api/hooks/use-find-recipient-mutation';
import { useRemitDC1CheckTrnscMutation } from '~/entities/exchange/api/hooks/use-remit-dc1-check-trnsc-mutation';
import { RecommendedBanks } from '~/entities/exchange-input-recipient/ui/recommended-banks';
import { WalletQRScanButton } from '~/entities/exchange-input-recipient/ui/wallet-qr-scan-button';
import { SubTitle } from '~/entities/exchange-select-recipient/ui/sub-title';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { useQRScanListener } from '~/entities/qr-scan/lib/use-qr-scan-listener';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { appConfig } from '~/shared/config';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useEffectOnceAfterPageRendered } from '~/shared/lib/hooks';
import { BankSelect } from '~/shared/ui/selects/bank-select';
import { TextInput } from '~/shared/ui/text-input/text-input';

//화면에 보여질 지갑 수
const INITIAL_VISIBLE_WALLET_COUNT = 5;

type InputRecipientPageProps = {
  context: 수취인_입력Context;
  onNext: ({ aliasNm, walletInsttCd, draftCd }: 수취인_입력Context) => void;
  onRefundNext: ({
    aliasNm,
    walletInsttCd,
    trnscAmt,
    personNm,
    shortBankName,
    draftCd,
    txCd,
  }: {
    aliasNm: string;
    walletInsttCd: string;
    trnscAmt: string;
    personNm: string;
    shortBankName: string;
    draftCd: string;
    txCd: string;
  }) => void;
  onError: (error: Error) => void;
};

export const InputRecipientPage = ({ onNext, onError, context, onRefundNext }: InputRecipientPageProps) => {
  useSetHeaderTitle(i18n.t('remittance'));
  // const { navigate } = useNavigate();

  const { data: userRes } = useGetUserInfoQuery({ staleTime: 0 });
  const { data: walletList = [] } = useGetCstmrWalletListQuery();
  const { comCode } = useComCodeState(COM_CODE.BANK);
  const [isWalletListExpanded, setIsWalletListExpanded] = useState(false);
  const form = useForm<수취인_입력Context>({
    mode: 'all',
    defaultValues: {
      aliasNm: context?.aliasNm ?? '',
      walletInsttCd: context?.walletInsttCd ?? '',
      personNm: context?.personNm ?? '',
    },
  });
  const formOptions = createFormOptions<수취인_입력Context>();

  const { handleSubmit, register, getValues, watch, setFocus, setValue, clearErrors } = form;
  const resetQRCode = useStore((state) => state.qrScannerSlice.resetQRCode);
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');

  const watchAllFields = watch();
  const { aliasNm, trnscAmt } = watchAllFields;
  const isDisabled = !watchAllFields.aliasNm || !watchAllFields.walletInsttCd;
  const isUserInfoReady = !!userRes.tbCstmrMastr?.cstmrNo;
  const userWalletList = isUserInfoReady
    ? walletList.filter((item) => item.aliasNm !== userRes.tbCstmrMastr?.dfltAliasNm)
    : [];
  const isWalletListExpandable = userWalletList.length > INITIAL_VISIBLE_WALLET_COUNT;

  const { mutateAsync: findRecipient } = useFindRecipientMutation();
  const { mutateAsync: remitDC1CheckTrnsc } = useRemitDC1CheckTrnscMutation();

  const requestRemittance = async (draftCd: string) => {
    const params: RemitRequestDTO = {
      tbAcnutMastr: {
        trnscAmt: context.trnscAmt,
        draftCd: draftCd ?? '',
      },
    };

    const remitRes = await remitDC1CheckTrnsc(params);

    return remitRes;
  };

  const onSubmit = async () => {
    if (isDisabled) return;
    const recipientData = await findRecipient({ aliasNm, trgetInstt: watchAllFields.walletInsttCd });

    if (!recipientData?.draftCd) return;

    if (isEmpty(context.trnscAmt)) {
      onNext({
        ...context,
        aliasNm: aliasNm ?? '',
        walletInsttCd: recipientData?.insttCd ?? '',
        personNm: recipientData?.personNm ?? '',
        draftCd: recipientData?.draftCd,
      });
    } else {
      const createTransResult = await requestRemittance(recipientData.draftCd);
      if (createTransResult.txCd) {
        onRefundNext({
          aliasNm: aliasNm ?? '',
          walletInsttCd: recipientData?.insttCd ?? '',
          trnscAmt: createTransResult.amt.toString() ?? '',
          personNm: recipientData?.personNm ?? '',
          shortBankName: '',
          draftCd: recipientData?.draftCd ?? '',
          txCd: createTransResult?.txCd,
        });
      }
    }
  };

  useEffectOnceAfterPageRendered(() => {
    setFocus('aliasNm');
  });

  useEffect(() => {
    return () => {
      resetQRCode();
    };
  }, [resetQRCode]);

  useEffect(() => {
    setIsWalletListExpanded(false);
  }, [isUserInfoReady, walletList, userRes.tbCstmrMastr?.dfltAliasNm]);

  useQRScanListener((scannedQRCode) => {
    setValue('aliasNm', scannedQRCode.walletAddr ?? '');
    setValue('walletInsttCd', scannedQRCode.bankCode ?? '');
    clearErrors('aliasNm');
    clearErrors('walletInsttCd');
    resetQRCode();
  });

  const handleClick = (clickedItem: UserWalletResponse) => () => {
    handleSelectRecipient(clickedItem);
  };

  const handleSelectRecipient = (item: UserWalletResponse) => {
    setValue('aliasNm', item.aliasNm!);
    setValue('walletInsttCd', item.bankCd!);
  };

  const handleExpandWalletList = () => {
    if (userWalletList.length <= INITIAL_VISIBLE_WALLET_COUNT) return;
    setIsWalletListExpanded((prev) => !prev);
  };

  return (
    <FormProvider {...form}>
      <div className="wrap bgw">
        <div className="content sub has-btm-btn">
          <SubTitle />
          <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area">
            <TextInput
              key={comCode?.tbSysCodeValueList?.[0].cdGroupId}
              label={i18n.t('enterWalletNumberOrScanQRCode')}
              {...register('aliasNm', {
                ...formOptions.ALIAS_NM,
                validate: {
                  notOwnWallet: (value: string) => {
                    const ownAliasNm = userRes?.tbCstmrMastr?.aliasNm ?? '';
                    if (!value || !ownAliasNm) return true;
                    return value !== ownAliasNm || i18n.t('validation:cannotSendToOwnWallet');
                  },
                },
              })}
              inputMode="numeric"
            />
            <BankSelect
              placeholder={i18n.t('selectBank')}
              register={register}
              name="walletInsttCd"
              option={formOptions.BANK_CODE}
            />
            <RecommendedBanks aliasNm={aliasNm} setValue={setValue} clearErrors={clearErrors} />
            {userWalletList.length > 0 && (
              <div className="recent-list wallet-recent-list">
                <div className="recent-list-header">
                  <span style={{ fontSize: 'var(--font-size-17)' }}>{i18n.t('myWallet')} </span>
                  <span
                    className={clsx('wallet-count-badge', {
                      expandable: isWalletListExpandable,
                      expanded: isWalletListExpanded,
                    })}
                    onClick={handleExpandWalletList}
                  >
                    {userWalletList.length}개
                  </span>
                </div>
                <ul
                  className={clsx('wallet-recent-items', {
                    expanded: isWalletListExpanded,
                    collapsed: isWalletListExpandable && !isWalletListExpanded,
                  })}
                >
                  {userWalletList.map((account, index) => (
                    <li
                      key={index}
                      className={clsx({
                        'wallet-item-extra': index >= INITIAL_VISIBLE_WALLET_COUNT,
                      })}
                    >
                      <button type="button" className="recent-btn" onClick={handleClick(account)}>
                        <span className={`recent-logo ${account.bankCd}`}>{i18n.t('bankLogo')}</span>
                        <div className="recent-text">
                          <span>{i18n.t('depositToken')}</span>
                          <span>{shortBankName}</span>
                        </div>
                        <div>
                          <span>{account.aliasNm}</span>
                        </div>
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </form>
        </div>
        <div className="btn-area">
          <button
            onClick={handleSubmit(onSubmit)}
            className={clsx('btm-btn app', { disabled: isDisabled })}
            id="transferBtn"
            disabled={isDisabled}
          >
            {i18n.t('next')}
          </button>
        </div>
        <WalletQRScanButton />
      </div>
    </FormProvider>
  );
};
