import { useMutation } from '@tanstack/react-query';
import { remitCheckResponseDTO, RemitRequestDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useRemitDC1CheckTrnscMutation = (
  options?: MutationOptions<RemitRequestDTO, CBDCAxiosError, remitCheckResponseDTO>,
) => {
  const mutation = useMutation<remitCheckResponseDTO, CBDCAxiosError, RemitRequestDTO>({
    ...options,
    mutationFn: (data: RemitRequestDTO) => exchangeApi.remitDC1CheckTrnsc(data),
  });

  return {
    ...mutation,
  };
};
