import { lazy } from 'react';
import { ExchangeFunnelProps } from '~/widgets/exchange-funnel-router/ui/exchange-funnel-router';
import { useRemittanceFunnel } from '~/widgets/exchange-remittance-funnel/lib/use-remittance-funnel';
import { FunnelStep } from '~/widgets/exchange-remittance-funnel/model/enums';
import {
  금액입력Context,
  금액확인Context,
  수취인_입력Context,
  완료Context,
  처리중Context,
  최근_수취인_선택Context,
} from '~/widgets/exchange-remittance-funnel/model/schemas';
import { InputRecipientPage } from './input-recipient-page';
import { SelectRecipientPage } from './select-recipient-page';

const InputAmountPage = lazy(() =>
  import('./input-amount-page').then((module) => ({ default: module.InputAmountPage })),
);
const InputConfirmPage = lazy(() =>
  import('./input-confirm-page').then((module) => ({ default: module.InputConfirmPage })),
);
const ProcessPage = lazy(() => import('./process-page').then((module) => ({ default: module.ProcessPage })));
const CompletePage = lazy(() => import('./complete-page').then((module) => ({ default: module.CompletePage })));

export const RemittanceFunnel = ({
  config,
  onProcessingStart,
  onProcessingSuccess,
  onProcessingError,
  onComplete,
}: ExchangeFunnelProps) => {
  const { funnel } = useRemittanceFunnel({
    //step: FunnelStep.최근_수취인_선택,
    step: FunnelStep.수취인_입력,
    context: {
      ...config,
    },
  });

  return (
    <funnel.Render
      최근_수취인_선택={({ context, history }) => (
        <SelectRecipientPage
          context={context as 최근_수취인_선택Context}
          onNext={() => {
            history.push(FunnelStep.수취인_입력, { ...context });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      수취인_입력={({ context, history }) => (
        <InputRecipientPage
          context={context as 수취인_입력Context}
          onNext={(onNextParams) => {
            history.push(FunnelStep.금액입력, { ...context, ...onNextParams });
          }}
          onRefundNext={(onNextParams) => {
            history.push(FunnelStep.금액확인, {
              ...context,
              ...onNextParams,
            });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      금액입력={({ context, history }) => (
        <InputAmountPage
          context={context as 금액입력Context}
          onNext={({ trnscAmt, personNm, shortBankName, txCd }) => {
            history.push(FunnelStep.금액확인, {
              ...context,
              trnscAmt,
              personNm,
              shortBankName,
              txCd,
            });
          }}
          onError={(error) => {
            console.error('[ExchangeFunnel] 금액입력 error:', error);
            onProcessingError?.(error);
          }}
        />
      )}
      금액확인={({ context, history }) => (
        <InputConfirmPage
          context={context as 금액확인Context}
          onNext={(params: 금액확인Context) => {
            onProcessingStart?.();
            history.push(FunnelStep.처리중, params);
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      처리중={({ context, history }) => (
        <ProcessPage
          context={context as 처리중Context}
          onNext={({ trnscId, reqAliasNm }) => {
            history.push(FunnelStep.완료, {
              ...context,
              trnscId,
              reqAliasNm,
            });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      완료={({ context }) => (
        <CompletePage
          context={context as 완료Context}
          onNext={({ redirectPath }) => {
            onComplete?.(redirectPath);
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
    />
  );
};
