import { ComCodeParams } from '~/entities/comcode/model/types';
import i18n from '~/shared/i18n/i18n';

type RecommendedBanksProps = {
  list: ComCodeParams[] | undefined;
  onItemClicked: (item: ComCodeParams) => void;
};
export const RecommendedBankList = ({ list, onItemClicked }: RecommendedBanksProps) => {
  const handleClick = (item: ComCodeParams) => () => {
    onItemClicked?.(item);
  };
  return (
    <div className="recomed-bank">
      {(!list || list?.length === 0) && (
        <p className="reco-info">{i18n.t('text:enterWalletNumberForBankRecommendation')}</p>
      )}
      {list?.map((item) => (
        <button
          key={item.cdValueId}
          type="button"
          className={`on reco-bank-btn ${item.cdValue}`}
          data-banknm={item.cdValueNm}
          onClick={handleClick(item)}
        >
          {item.cdValueNm}
        </button>
      ))}
    </div>
  );
};
