import { useMemo } from 'react';
import { UseFormSetValue, UseFormClearErrors } from 'react-hook-form';
import { 수취인_입력Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { ComCodeParams } from '~/entities/comcode/model/types';
import { RecommendedBankList } from './recommended-bank-list';

type RecommendedBanksProps = {
  aliasNm: string;
  setValue: UseFormSetValue<수취인_입력Context>;
  clearErrors: UseFormClearErrors<수취인_입력Context>;
};
export const RecommendedBanks = ({ aliasNm, setValue, clearErrors }: RecommendedBanksProps) => {
  const { comCode } = useComCodeState(COM_CODE.BANK);

  const recommendedBanks = useMemo(() => {
    if (aliasNm?.length < 2) {
      return [];
    }

    const keyword = aliasNm?.slice(1, 4).trim();
    return comCode?.tbSysCodeValueList
      ?.filter((item) => {
        return (item?.atrb2 ?? '').includes(keyword);
      })
      .slice(0, 3);
  }, [aliasNm]);

  const handleRecommendedBankClicked = (item: ComCodeParams) => {
    setValue('walletInsttCd', item.cdValue!);
    clearErrors('walletInsttCd');
  };
  return <RecommendedBankList list={recommendedBanks} onItemClicked={handleRecommendedBankClicked} />;
};
