import { useEffect } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { useStore } from '~/app/store/store';
import { 최근_수취인_선택Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useSetHeaderTitle, useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { WalletQRScanButton } from '~/entities/exchange-input-recipient/ui/wallet-qr-scan-button';
import { SubTitle } from '~/entities/exchange-select-recipient/ui/sub-title';
import { useQRScanListener } from '~/entities/qr-scan/lib/use-qr-scan-listener';
import { WalletItemDTO } from '~/entities/wallet/api/dtos/wallet-item';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { TextInput } from '~/shared/ui/text-input/text-input';

type SelectRecipientPageProps = {
  context: 최근_수취인_선택Context;
  onNext: (params: { tokenId: string; trnscTypeCd: TrnscTypeCd; aliasNm: string; walletInsttCd: string }) => void;
  onError: (error: Error) => void;
};

export const SelectRecipientPage = ({ onNext, onError, context }: SelectRecipientPageProps) => {
  useSetHeaderTitle(i18n.t('remittance'));

  const form = useForm<최근_수취인_선택Context>({ mode: 'all' });
  const { register } = form;
  const resetQRCode = useStore((state) => state.qrScannerSlice.resetQRCode);

  const moveToInputRecipient = () => {
    onNext({
      ...context,
    });
  };

  //최근 보낸 사람
  const handleSelectRecipient = (item: WalletItemDTO) => {
    // const param: InputRecipientParams = {
    //   ...state,
    //   aliasNm: item.aliasNm ?? '',
    //   walletInsttCd: item.walletInsttCd,
    //   tokenId: state.tokenId,
    // };

    // navigate(`${PATHS.exchange.root}`, {
    //   state: param,
    // });

    if (!item.aliasNm) {
      console.error('handleSelectRecipient ==> item.aliasNm is null', item);
      item.aliasNm = '';
    }

    onNext({
      tokenId: context.tokenId,
      trnscTypeCd: context.trnscTypeCd,
      aliasNm: item.aliasNm,
      walletInsttCd: item.walletInsttCd,
    });
  };

  useQRScanListener((scannedQRCode) => {
    // const param: InputRecipientParams = {
    //   ...state,
    //   aliasNm: scannedQRCode.walletAddr ?? '',
    //   walletInsttCd: scannedQRCode.placeBankCode ?? '',
    // };
    // navigate(`${PATHS.exchange.root}`, {
    //   state: param,
    // });

    onNext({
      aliasNm: scannedQRCode.walletAddr ?? '',
      walletInsttCd: scannedQRCode.placeBankCode ?? '',
      tokenId: context.tokenId,
      trnscTypeCd: context.trnscTypeCd,
    });
    resetQRCode();
  });

  useSetOnBack(() => {
    window.close();
  });

  useEffect(() => {
    return () => {
      resetQRCode();
    };
  }, [resetQRCode]);

  return (
    <div className="wrap bgw">
      <div className="content sub has-btm-btn">
        <SubTitle />
        <FormProvider {...form}>
          <form className="ipt-form-area no-flex">
            <TextInput
              label={i18n.t('enterWalletNumberOrScanQRCode')}
              description={i18n.t('text:enterWalletNumberForBankRecommendation')}
              {...register('aliasNm')}
              isErrorPaddingPresent={false}
              onClick={moveToInputRecipient}
              readOnly
            />
          </form>
        </FormProvider>
        {/* 최근 보낸 사람 */}
        {/* <RecentRecipientList onClickItem={handleSelectRecipient} /> */}
      </div>
      <WalletQRScanButton />
    </div>
  );
};
