import { useFunnel } from '@use-funnel/react-router-dom';
import { FunnelStep } from '~/widgets/exchange-remittance-funnel/model/enums';
import {
  FunnelContextMap,
  금액입력_Schema,
  금액확인_Schema,
  수취인_입력_Schema,
  완료_Schema,
  처리중_Schema,
  최근_수취인_선택_Schema,
} from '~/widgets/exchange-remittance-funnel/model/schemas';
import { BaseExchangeContext } from '~/entities/exchange';

export const useRemittanceFunnel = (initialConfig?: { step?: FunnelStep; context?: Partial<BaseExchangeContext> }) => {
  const initialStep = initialConfig?.step || FunnelStep.최근_수취인_선택;
  const initialContext = {
    ...(initialConfig?.context || {}),
  };

  const funnel = useFunnel<FunnelContextMap>({
    id: 'remittance-funnel',
    steps: {
      [FunnelStep.최근_수취인_선택]: { parse: 최근_수취인_선택_Schema.parse },
      [FunnelStep.수취인_입력]: { parse: 수취인_입력_Schema.parse },
      [FunnelStep.금액입력]: { parse: 금액입력_Schema.parse },
      [FunnelStep.금액확인]: { parse: 금액확인_Schema.parse },
      [FunnelStep.처리중]: { parse: 처리중_Schema.parse },
      [FunnelStep.완료]: { parse: 완료_Schema.parse },
    },
    initial: {
      step: initialStep,
      context: {
        aliasNm: '',
        walletInsttCd: '',
        ...initialContext,
      },
    },
  });

  return {
    funnel,
  };
};
